export const ENTRIES: readonly KnowledgeEntry[] = ROWS.map(
  ([term, translation, group, definition, example, exampleEs], i) => ({
    id: `term-${i + 1}`,
    term,
    translation,
    group,
    definition,
    example,
    exampleEs,
  }),
);

/** The 13 areas, in order of first appearance (v1.8 `new Set(ENTRIES.map(x => x.group))`). */
export const KNOWLEDGE_GROUPS: readonly string[] = [...new Set(ENTRIES.map((e) => e.group))];

/** Practice cards: the entries with an example (21). */
export const PRACTICE_CARDS: readonly KnowledgeEntry[] = ENTRIES.filter((e) => e.example);

